1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<title>Thursday study group</title>
6	<style>
7	  html { font: 18px/1.55 Georgia, serif; color: #1F1E1B; background: #F2F0E9; }
8	  body { max-width: 34rem; margin: 3rem auto; padding: 0 1.2rem; }
9	  h1 { font-weight: 500; font-size: 1.6rem; margin: 0 0 0.4rem; }
10	  p.meta { color: #6b665e; margin: 0 0 1.6rem; }
11	  form { display: grid; gap: 0.9rem; }
12	  label { display: block; font-size: 0.95rem; }
13	  input.field {
14	    display: block; width: 100%; padding: 0.55rem 0.7rem; font: inherit;
15	    border: 1px solid #1F1E1B; background: transparent; box-sizing: border-box;
16	  }
17	  button {
18	    padding: 0.55rem 1.1rem; font: inherit; color: #F2F0E9;
19	    background: #D97757; border: 0; cursor: pointer; justify-self: start;
20	  }
21	  .ok { margin-top: 0.6rem; color: #1F6F5C; }
22	</style>
23	</head>
24	<body>
25	  <h1>Thursday study group</h1>
26	  <p class="meta">Thursdays, 6 pm, second-floor lounge.
27	    <span id="when"></span></p>
28	  <form id="f" onsubmit="return signup(event)">
29	    <label>First name
30	      <input class="field" type="text" id="name" name="name"
31	             autocomplete="given-name" required>
32	    </label>
33	    <button type="submit">Sign me up</button>
34	    <p class="ok" id="ok" hidden>You are on the list, <span id="who"></span>.</p>
35	  </form>
36	  <script>
37	    (function () {
38	      var now = new Date();
39	      var offset = (4 - now.getDay() + 7) % 7;
40	      var t = new Date(now); t.setDate(now.getDate() + (offset || 7));
41	      var opts = { weekday: "long", month: "long", day: "numeric" };
42	      document.getElementById("when").textContent =
43	        "Next: " + t.toLocaleDateString(undefined, opts) + ".";
44	    })();
45	    function signup(e) {
46	      e.preventDefault();
47	      document.getElementById("who").textContent =
48	        document.getElementById("name").value.trim() || "friend";
49	      document.getElementById("ok").hidden = false;
50	      return false;
51	    }
52	  </script>
53	</body>
54	</html>
